app.put('/api/me/password',auth,authLimiter,wrap(async(req,res)=>{const {current,next}=req.body||{};if(typeof next!=='string'||next.length<10)throw fail(400,'A nova senha precisa ter pelo menos 10 caracteres');const [[u]]=await pool.execute('SELECT * FROM users WHERE id=?',[req.user.id]);if(!u||!await bcrypt.compare(String(current||''),u.password_hash))throw fail(401,'Senha atual incorreta');await pool.execute('UPDATE users SET password_hash=? WHERE id=?',[await bcrypt.hash(next,12),u.id]);await audit(req,'password_changed');res.json({ok:true})}));
