app.post('/api/evaluations',auth,wrap(async(req,res)=>{if(!req.body.patient_id)throw fail(400,'Paciente obrigatório');const id=randomUUID();const v=idInput(req.body);const modelId=await usableModel(req.body.model_id);await pool.execute('INSERT INTO evaluations(id,patient_id,created_by,sex,schooling,start_date,end_date,model_id) VALUES(?,?,?,?,?,?,?,?)',[id,req.body.patient_id,req.user.id,v.sex,v.schooling,v.start_date,v.end_date,modelId]);await audit(req,'evaluation_created',id);res.status(201).json({id,status:'draft'})}));
app.get('/api/evaluations/:id',auth,wrap(async(req,res)=>{const e=await evaluation(req.params.id);const[docs]=await pool.execute('SELECT id,kind,filename,created_at FROM documents WHERE evaluation_id=?',[e.id]);const[sections]=await pool.execute('SELECT * FROM sections WHERE evaluation_id=? ORDER BY section_key',[e.id]);res.json({evaluation:{...e,age:ageText(e.birth_date,e.end_date)},documents:docs,sections,usage:await usageSummary('evaluation_id=?',[e.id])})}));
// ---- Identification (top of the report) ----
const ISO_DATE=/^\d{4}-\d{2}-\d{2}$/;
const toBr=iso=>ISO_DATE.test(iso||'')?iso.split('-').reverse().join('/'):'';
function fromBr(v){const m=String(v||'').trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);if(!m)return null;const iso=`${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`;const d=new Date(iso+'T00:00:00Z');return !isNaN(d)&&d.toISOString().slice(0,10)===iso?iso:null}
function ageText(birth,at){if(!ISO_DATE.test(birth||''))return '';const ref=ISO_DATE.test(at||'')?at:new Date().toISOString().slice(0,10);const [by,bm,bd]=birth.split('-').map(Number),[ry,rm,rd]=ref.split('-').map(Number);let y=ry-by;if(rm<bm||(rm===bm&&rd<bd))y--;if(y<0)return '';if(y<2){let mo=(ry-by)*12+rm-bm-(rd<bd?1:0);return mo===1?'1 mês':`${mo} meses`}return `${y} anos`}
// Values written into the base copy; empty ones leave the base text as it is.
function reportFields(e){return Object.fromEntries(Object.entries({'Nome':e.patient_name,'Data de Nascimento':toBr(e.birth_date),'Idade':ageText(e.birth_date,e.end_date),'Sexo':e.sex,'Escolaridade':e.schooling,'Data de início da avaliação':toBr(e.start_date),'Data da finalização do laudo':toBr(e.end_date)}).filter(([,v])=>v&&String(v).trim()))}
const idInput=b=>({name:String(b?.name||'').replace(/\s+/g,' ').trim(),birth_date:ISO_DATE.test(b?.birth_date||'')?b.birth_date:null,sex:String(b?.sex||'').trim().slice(0,40)||null,schooling:String(b?.schooling||'').trim().slice(0,120)||null,start_date:ISO_DATE.test(b?.start_date||'')?b.start_date:null,end_date:ISO_DATE.test(b?.end_date||'')?b.end_date:null});
app.put('/api/evaluations/:id/identification',auth,role('admin','psychologist'),wrap(async(req,res)=>{const e=await evaluation(req.params.id);if(e.status==='approved')throw fail(409,'Avaliação aprovada: identificação travada');const v=idInput(req.body);if(v.name.length<2)throw fail(400,'Nome obrigatório');await pool.execute('UPDATE patients SET name=?,birth_date=? WHERE id=?',[v.name,v.birth_date,e.patient_id]);await pool.execute('UPDATE evaluations SET sex=?,schooling=?,start_date=?,end_date=? WHERE id=?',[v.sex,v.schooling,v.start_date,v.end_date,e.id]);await audit(req,'identification_updated',e.id);res.json({ok:true,age:ageText(v.birth_date,v.end_date)})}));
// Fills only empty fields from what the intern already typed in the base document.
async function prefillFromBase(e,found){if(!found)return;const birth=fromBr(found['Data de Nascimento']);if(!e.birth_date&&birth)await pool.execute('UPDATE patients SET birth_date=? WHERE id=?',[birth,e.patient_id]);const set={sex:found['Sexo'],schooling:found['Escolaridade'],start_date:fromBr(found['Data de início da avaliação']),end_date:fromBr(found['Data da finalização do laudo'])};for(const [col,val] of Object.entries(set)){const v=String(val||'').trim();if(v&&v!=='-'&&!e[col])await pool.execute(`UPDATE evaluations SET ${col}=? WHERE id=?`,[v,e.id])}}
