function priceFor(model){if(process.env.OPENAI_PRICE_INPUT&&process.env.OPENAI_PRICE_OUTPUT)return [Number(process.env.OPENAI_PRICE_INPUT),Number(process.env.OPENAI_PRICE_CACHED||process.env.OPENAI_PRICE_INPUT),Number(process.env.OPENAI_PRICE_OUTPUT)];const k=Object.keys(PRICES).sort((a,b)=>b.length-a.length).find(k=>model.startsWith(k));return k?PRICES[k]:null}
function costUsd(model,u){const p=priceFor(model);if(!p)return null;const cached=Math.min(u.cached||0,u.input);return ((u.input-cached)*p[0]+cached*p[1]+u.output*p[2])/1e6}
