// ---------- PDF: the approved Word converted on this computer (Microsoft Word, or LibreOffice when installed) ----------
const PDF_SCRIPT=path.join(path.dirname(WORKER||''),'docx_to_pdf.ps1');
const SOFFICE=[process.env.SOFFICE_PATH,'C:/Program Files/LibreOffice/program/soffice.exe','C:/Program Files (x86)/LibreOffice/program/soffice.exe','/usr/bin/soffice','/usr/bin/libreoffice','/Applications/LibreOffice.app/Contents/MacOS/soffice'].filter(Boolean).find(p=>existsSync(p));
const run=(cmd,args,ms)=>new Promise(resolve=>{const p=spawn(cmd,args,{windowsHide:true,timeout:ms});let err='';p.stderr.on('data',d=>err+=d);p.on('error',()=>resolve({code:-1,err:'spawn'}));p.on('close',code=>resolve({code,err:err.slice(0,200)}))});
let pdfChain=Promise.resolve();
/** DOCX bytes -> PDF bytes. One conversion at a time; the temporary files only exist during the conversion. */
function toPdf(bytes){
 const job=pdfChain.then(async()=>{
  await fs.mkdir(STORAGE,{recursive:true,mode:0o700});const id=randomUUID(),dir=path.join(STORAGE,'pdf-'+id),src=path.join(dir,'laudo.docx'),out=path.join(dir,'laudo.pdf');
  await fs.mkdir(dir,{mode:0o700});
  try{
   await fs.writeFile(src,bytes,{mode:0o600});
   let r;
   if(SOFFICE)r=await run(SOFFICE,['--headless','--norestore','--convert-to','pdf','--outdir',dir,src],120000);
   else if(process.platform==='win32'&&existsSync(PDF_SCRIPT)){r=await run('powershell',['-NoProfile','-ExecutionPolicy','Bypass','-File',PDF_SCRIPT,src,out],120000);if(r.code===2)throw fail(503,'Para gerar PDF, instale o Microsoft Word ou o LibreOffice neste computador.')}
   else throw fail(503,'Para gerar PDF, instale o LibreOffice (ou o Microsoft Word no Windows).');
   if(r.code!==0||!existsSync(out)){console.error('[pdf]',r.err);throw fail(500,'Não foi possível gerar o PDF. Baixe o Word e salve como PDF por ele.')}
   const pdf=await fs.readFile(out);if(pdf.subarray(0,5).toString()!=='%PDF-')throw fail(500,'O PDF gerado é inválido.');return pdf;
  }finally{await fs.rm(dir,{recursive:true,force:true})}
 });
 pdfChain=job.catch(()=>{});return job;
}
