// Reads a DOCX with the worker and returns its check list. The file only exists on disk while it is read.
async function inspectModel(buffer,audience){
 if(buffer.subarray(0,2).toString()!=='PK')throw fail(400,'Arquivo não é um Word (.docx) válido');
 await fs.mkdir(STORAGE,{recursive:true,mode:0o700});const tmp=path.join(STORAGE,randomUUID()+'.docx');
 try{await fs.writeFile(tmp,buffer,{mode:0o600});return modelReport(await docx('inspect',[tmp]),audience)}
 catch(err){if(err.status===400)throw err;throw fail(400,'Não foi possível ler este Word. Abra no Word, salve como .docx e envie de novo.')}
 finally{await fs.rm(tmp,{force:true})}
}
const modelRow=(m,v)=>({id:m.id,name:m.name,description:m.description,audience:m.audience,tags:JSON.parse(m.tags_json||'[]'),active:!!m.active,created_at:m.created_at,updated_at:m.updated_at,
 version:v?{version:v.version,filename:v.filename,created_at:v.created_at,note:v.note,report:JSON.parse(v.report_json)}:null});
async function reportModel(id){const [[m]]=await pool.execute('SELECT * FROM report_models WHERE id=?',[id]);if(!m)throw fail(404,'Modelo não encontrado');return m}
async function currentVersion(id){const [[v]]=await pool.execute('SELECT * FROM report_model_versions WHERE model_id=? ORDER BY version DESC LIMIT 1',[id]);return v}
async function addVersion(req,modelId,buffer,filename,note,report){
 const [[{n}]]=await pool.execute('SELECT COALESCE(MAX(version),0) n FROM report_model_versions WHERE model_id=?',[modelId]);
 const key=await store(buffer);const hash=createHash('sha256').update(buffer).digest('hex');
 await pool.execute('INSERT INTO report_model_versions(id,model_id,version,filename,storage_path,sha256,report_json,note,created_by) VALUES(?,?,?,?,?,?,?,?,?)',[randomUUID(),modelId,n+1,String(filename||'modelo.docx').slice(0,200),key,hash,JSON.stringify(report),String(note||'').trim().slice(0,300),req.user.id]);
 await pool.execute('UPDATE report_models SET updated_at=CURRENT_TIMESTAMP WHERE id=?',[modelId]);return n+1;
}
